from __future__ import absolute_import
import os
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sc.pages.view import ViewPanel
from taf.selenium.sc.common.exceptions import ExpectedMessageDisplayFailure
from taf.selenium.sc.pages.navigatable_page import NavigatablePage
from taf.selenium.sc.pages.configuration_management.configuration_menu import ConfigurationMenu


class ConfigureFromaFilePage(NavigatablePage):

    _TARGET_TAB_XPATH = '//*[@id="commissioning-header"]//span[contains(text(), "Configure from a file")]'
    _MENU_ROUTE_LIST = ["commissioning", "Load file", _TARGET_TAB_XPATH]

    def __init__(self, driver):
        super(ConfigureFromaFilePage, self).__init__(driver, ConfigurationMenu)
        self._load_commissioning_file_panel = LoadCommissioningFilePanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def load_and_activate_configuration(self, file_path, timeout):
        return self._load_commissioning_file_panel.load_and_activate_configuration(file_path, timeout)

    def load_and_save_configuration_file(self, scf_file_path, timeout):
        return self._load_commissioning_file_panel.load_and_save_configuration_file(scf_file_path, timeout)


class LoadCommissioningFilePanel(ViewPanel):

    _SELECT_FILE_HIDDEN_ID = "file"
    _SELECT_FILE_HIDDEN_XPATH = '//input[@id="file"]'

    _ACTIVATION_BUTTON = '//*[@id="run-activation-btn"]/div/span'
    _NEXT_BUTTION = '//*[@id="stepper-next-button"]'
    _SAVE_BUTTION = '//*[@id="run-save-file-btn"]/div/span'

    _MESSAGE_XPATH_AFTER_LOAD_FILE = '//*[@id="warning-message-description"] | //div[@class="center title"]/h4'
    _MESSAGE_TEXT_AFTER_LOAD_FILE = ["If you continue, migration to the version below will be performed.",
                                     "You can now save the file and/or proceed with plan activation."]

    _MESSAGE_XPATH_AFTER_ACTIVATE = '//*[@id="reset-message-description"]/li[1]/span/b'
    _MESSAGE_TEXT_AFTER_ACTIVATE = "To proceed with activation and ASiR reset, click Next."

    _FINAL_MESSAGE_XPATH_AFTER_COMMISSIONING = '//*[@id="commissioning-wrapper"]//div[@class="text-wrapper"]'

    _OVERWRITE_BUTTON_XPATH = "//button[contains(text(), 'Overwrite')]"

    def __init__(self, driver):
        super(LoadCommissioningFilePanel, self).__init__(driver)

    def load_and_activate_configuration(self, file_path, timeout):
        self._close_overwrite_modal(timeout)

        abs_file_path = os.path.abspath(file_path)
        self._load_file(abs_file_path)

        self._wait_until_message_display(locator=(By.XPATH, self._MESSAGE_XPATH_AFTER_LOAD_FILE),
                                         message=self._MESSAGE_TEXT_AFTER_LOAD_FILE)
        self._click_next(timeout)
        self._click_activation(timeout)

        self._wait_until_message_display(locator=(By.XPATH, self._MESSAGE_XPATH_AFTER_ACTIVATE),
                                         message=self._MESSAGE_TEXT_AFTER_ACTIVATE)

        self._click_next(timeout)

        return self._collect_commissioning_file_result()

    def _load_file(self, file_path):
        self.load_file_from_hidden_button(button_location=self._SELECT_FILE_HIDDEN_ID,
                                          button_xpath=self._SELECT_FILE_HIDDEN_XPATH,
                                          file_path=file_path)

    def _click_activation(self, timeout):
        locator = (By.XPATH, self._ACTIVATION_BUTTON)
        if self._is_element_enabled(locator=locator, timeout=timeout):
            self.click_enabled_element_after_visible(locator=locator)

    def _click_next(self, timeout):
        locator = (By.XPATH, self._NEXT_BUTTION)
        if self._is_element_enabled(locator=locator, timeout=timeout):
            self.click_enabled_element_after_visible(locator=locator)

    def _close_overwrite_modal(self, timeout):
        locator = (By.XPATH, self._OVERWRITE_BUTTON_XPATH)
        if self._is_element_enabled(locator=locator, timeout=timeout):
            self.click_enabled_element_after_visible(locator=locator)

    def _collect_commissioning_file_result(self, timeout=300):
        try:
            element = self.fetch_element_until_is_visible(
                locator=(By.XPATH, self._FINAL_MESSAGE_XPATH_AFTER_COMMISSIONING), timeout=timeout)

        except TimeoutException:
            raise ExpectedMessageDisplayFailure("expected message is not displayed")

        return element.text

    def _wait_until_message_display(self, locator, message, timeout=10):
        try:
            element = self.fetch_element_until_is_visible(locator, timeout)
        except TimeoutException:
            raise ExpectedMessageDisplayFailure("{} message element not found".format(locator))

        if element.text.strip() not in message:
            raise ExpectedMessageDisplayFailure(
                "expected message '{}' not found, actual message is '{}'".format(message, element.text))

    def load_and_save_configuration_file(self, scf_file_path, timeout):
        self._close_overwrite_modal(timeout)

        abs_file_path = os.path.abspath(scf_file_path)
        self._load_file(abs_file_path)
        self._wait_until_message_display(locator=(By.XPATH, self._MESSAGE_XPATH_AFTER_LOAD_FILE),
                                         message=self._MESSAGE_TEXT_AFTER_LOAD_FILE)
        self._click_next(timeout)
        self._click_save(timeout)

    def _click_save(self, timeout):
        locator = (By.XPATH, self._SAVE_BUTTION)
        if self._is_element_enabled(locator=locator, timeout=timeout):
            self.click_enabled_element_after_visible(locator=locator)
